"""Independent, deliberately naive reference implementation of PROTOCOL.md v3.0.

Used only for differential testing of the submission; shares no code with it.
"""
from decimal import Decimal, getcontext, ROUND_DOWN
from fractions import Fraction
from itertools import product
import math

getcontext().prec = 120
PAD = 1514
VMAX = 3028
D = Decimal


def real(vals):
    for i, v in enumerate(vals):
        if v == PAD:
            return vals[:i]
    return list(vals)


def fragments_of(spec):
    width = spec['width']
    out = []
    for ri, row in enumerate(spec['discovery']):
        vals = row['values']
        acts = row['activation']
        n = len(real(vals))
        if n == 0:
            continue
        a = [D(x) for x in acts[:n]]
        mean = sum(a)/D(n)
        var = sum((x-mean)**2 for x in a)/D(n)
        sd = var.sqrt()
        thr = mean+sd
        high = [x > thr for x in a]
        i = 0
        while i < n:
            if not high[i]:
                i += 1
                continue
            j = i
            while j < n and high[j]:
                j += 1
            run = j-i
            if run >= 2:
                if run <= width:
                    out.append((ri, i, run, tuple(vals[i:j]), row['class']))
                else:
                    best = None
                    bs = None
                    for s in range(i, j-width+1):
                        cur = sum(acts[s:s+width])
                        if best is None or cur > best:
                            best = cur
                            bs = s
                    out.append((ri, bs, width, tuple(vals[bs:bs+width]), row['class']))
            i = j
    return out


def dist_ok(a, b, eps):
    L = len(a)
    total = 0
    anchors = 0
    for x, y in zip(a, b):
        d = abs(x-y)
        if (x < PAD < y) or (y < PAD < x):
            d += 1000
        total += d*d
        if x == y:
            anchors += 1
    p, q = eps
    # sqrt(total/L)*(3/5)^A <= p/q   <=>   total*q^2*9^A <= L*p^2*25^A
    return total*(q**2)*(9**anchors) <= L*(p**2)*(25**anchors)


def cluster_of(spec, frags):
    classes = spec['classes']
    eps = spec['eps']
    rn, rd = spec['ratio']
    per_class = {}
    for fid, f in enumerate(frags):
        per_class.setdefault(f[4], []).append(fid)
    groups = {}
    for fid, f in enumerate(frags):
        groups.setdefault((f[4], f[2]), []).append(fid)
    core = {}
    adj = {}
    for (cls, L), ids in groups.items():
        m = len(per_class[cls])
        dmin = max(2, -((-m*rn)//rd))
        for i in ids:
            nbrs = [j for j in ids if dist_ok(frags[i][3], frags[j][3], eps)]
            adj[i] = nbrs
            core[i] = len(nbrs) >= dmin
    # components over cores
    parent = {}

    def find(x):
        parent.setdefault(x, x)
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[max(ra, rb)] = min(ra, rb)
    for i in list(adj):
        if core[i]:
            find(i)
    for i in list(adj):
        if not core[i]:
            continue
        for j in adj[i]:
            if core[j]:
                union(i, j)
    comps = {}
    for i in list(adj):
        if core[i]:
            comps.setdefault(find(i), []).append(i)
    cid_of = {}
    clusters = {}
    for root, seeds in comps.items():
        cid = min(seeds)
        for s in seeds:
            cid_of[s] = cid
        clusters[cid] = {'id': cid, 'class': frags[cid][4], 'members': sorted(seeds),
                         'core': sorted(seeds), 'length': frags[cid][2]}
    noise = []
    for i in sorted(adj):
        if core[i]:
            continue
        cands = [cid_of[j] for j in adj[i] if core[j]]
        if not cands:
            noise.append(i)
        else:
            clusters[min(cands)]['members'].append(i)
    for c in clusters.values():
        c['members'] = sorted(c['members'])
    return clusters, sorted(noise)


def bounds_of(spec, cluster, frags):
    vals = [frags[m][3] for m in cluster['members']]
    L = cluster['length']
    out = []
    n = len(vals)
    for j in range(L):
        col = [v[j] for v in vals]
        mean = sum(D(x) for x in col)/D(n)
        var = sum((D(x)-mean)**2 for x in col)/D(n)
        sd = var.sqrt()
        lo = min(col)
        hi = max(col)
        a = (D(lo)-sd).to_integral_value(rounding=ROUND_DOWN)
        b = (D(hi)+sd).to_integral_value(rounding=ROUND_DOWN)
        out.append([max(0, int(a)), min(VMAX, int(b))])
    return out


def matches(row_vals, bounds):
    L = len(bounds)
    if len(row_vals) < L:
        return False
    for s in range(len(row_vals)-L+1):
        ok = True
        for j in range(L):
            v = row_vals[s+j]
            if not (bounds[j][0] <= v <= bounds[j][1]):
                ok = False
                break
        if ok:
            return True
    return False


def calibrate(spec, clusters, bounds):
    classes = spec['classes']
    rows = [(r['class'], real(r['values'])) for r in spec['validation']]
    counts = [0]*classes
    for c, _ in rows:
        counts[c] += 1
    thr = Fraction(*spec['threshold'])
    res = {}
    for cid in sorted(clusters):
        cl = clusters[cid]
        b = bounds[cid]
        hits = [0]*classes
        for c, vals in rows:
            if matches(vals, b):
                hits[c] += 1
        t = cl['class']
        cin = Fraction(hits[t], counts[t])
        others = [Fraction(hits[c], counts[c]) for c in range(classes) if c != t]
        cout = max(others) if others else Fraction(0)
        score = cin/(cout+Fraction(1, 10000))
        res[cid] = (hits, score, score > thr)
    return res


def feats_of(vals, width):
    f = list(vals[:width])
    while len(f) < width:
        f.append(PAD)
    return f


def train_tree(spec):
    import numpy as np
    from sklearn.tree import DecisionTreeClassifier
    X = np.array([feats_of(r['values'], spec['width']) for r in spec['train']], dtype=np.float32)
    y = np.array([r['class'] for r in spec['train']], dtype=np.int64)
    m = DecisionTreeClassifier(max_depth=10, random_state=42, class_weight='balanced').fit(X, y)
    t = m.tree_
    nodes = []
    for i in range(t.node_count):
        if t.children_left[i] == -1:
            v = t.value[i][0]
            best = 0
            for k in range(1, len(v)):
                if v[k] > v[best]:
                    best = k
            nodes.append([int(m.classes_[best])])
        else:
            nodes.append([int(t.feature[i]), int(round(2*float(t.threshold[i]))),
                          int(t.children_left[i]), int(t.children_right[i])])
    return nodes


def predict(nodes, feats):
    i = 0
    while len(nodes[i]) == 4:
        f, t2, l, r = nodes[i]
        i = l if 2*feats[f] <= t2 else r
    return nodes[i][0]


def key_count(bounds):
    tot = 1
    for lo, hi in bounds:
        s = hi-lo+1
        if lo <= PAD <= hi:
            s -= 1
        if s <= 0:
            return 0
        tot *= s
    return tot


def exact_entries(bounds_list, cap):
    keys = set()
    for b in bounds_list:
        if key_count(b) >= cap:
            return min(cap, key_count(b)) if cap else 0
    for b in bounds_list:
        axes = []
        for lo, hi in b:
            axes.append([v for v in range(lo, hi+1) if v != PAD])
        for k in product(*axes):
            keys.add(k)
            if len(keys) >= cap:
                return cap
    return min(len(keys), cap)


class Invalid(Exception):
    pass


def need(cond):
    if not cond:
        raise Invalid()


def solve(req):
    cap = req['capacity']
    catalog = []
    info = {}
    nfrag = 0
    for spec in req['releases']:
        frags = fragments_of(spec)
        nfrag += len(frags)
        need(nfrag <= 4096)
        clusters, noise = cluster_of(spec, frags)
        bounds = {cid: bounds_of(spec, clusters[cid], frags) for cid in clusters}
        cal = calibrate(spec, clusters, bounds)
        prio = sorted([cid for cid in clusters if cal[cid][2]],
                      key=lambda c: (-cal[c][1], c))
        nodes = train_tree(spec)
        if spec['mode'] == 'range':
            entries = len(prio)
        else:
            entries = exact_entries([bounds[c] for c in prio], cap['exact']+1)
        catalog.append({
            'id': spec['id'],
            'fragments': [[f[0], f[1], f[2]] for f in frags],
            'noise': noise,
            'clusters': [{'id': cid, 'class': clusters[cid]['class'],
                          'members': clusters[cid]['members'], 'core': clusters[cid]['core'],
                          'range': bounds[cid], 'hits': cal[cid][0],
                          'score': [cal[cid][1].numerator, cal[cid][1].denominator],
                          'kept': cal[cid][2]} for cid in sorted(clusters)],
            'priority': prio,
            'backup': nodes,
            'entries': entries,
        })
        info[spec['id']] = {'mode': spec['mode'], 'entries': entries, 'width': spec['width'],
                            'packet_limit': spec['packet_limit'], 'idle_us': spec['idle_us'],
                            'nodes': nodes,
                            'prio': [(cid, clusters[cid]['class'], bounds[cid]) for cid in prio]}
    installs = []
    decisions = []
    current = None
    residents = set()
    pins = {}
    epochs = {}
    opened = {}
    at = 0

    def used():
        r = e = 0
        for rid in residents:
            if info[rid]['mode'] == 'range':
                r += info[rid]['entries']
            else:
                e += info[rid]['entries']
        return {'range': r, 'exact': e}

    def commit(ep, reason, seen, rule, start, cls):
        ri = info[ep['rid']]
        if cls is None:
            f = ep['feats'][:ri['width']]
            while len(f) < ri['width']:
                f.append(PAD)
            cls = predict(ri['nodes'], f)
        ep['done'] = True
        decisions.append({'flow': ep['flow'], 'epoch': ep['num'], 'release': ep['rid'],
                          'at': at, 'seen': seen, 'class': cls, 'reason': reason,
                          'rule': rule, 'start': start})

    for block in req['blocks']:
        for op in block:
            kind = op[0]
            ident = op[1]
            if kind == 'install':
                ri = info[ident]
                pool = cap[ri['mode']]
                prev = current
                freed = prev is not None and prev != ident and pins.get(prev, 0) == 0
                status = 'ok'
                if ri['entries'] > pool:
                    status = 'oversize'
                else:
                    prospective = set(residents)
                    if freed:
                        prospective.discard(prev)
                    prospective.add(ident)
                    u = {'range': 0, 'exact': 0}
                    for rid in prospective:
                        u[info[rid]['mode']] += info[rid]['entries']
                    if u['range'] > cap['range'] or u['exact'] > cap['exact']:
                        status = 'busy'
                if status == 'ok':
                    if freed:
                        residents.discard(prev)
                    residents.add(ident)
                    current = ident
                installs.append({'at': at, 'id': ident, 'status': status,
                                 'resident': sorted(residents), 'used': used()})
            elif kind == 'open':
                need(current is not None)
                need(ident not in epochs)
                num = opened.get(ident, 0)
                opened[ident] = num+1
                pins[current] = pins.get(current, 0)+1
                residents.add(current)
                epochs[ident] = {'flow': ident, 'num': num, 'rid': current, 'feats': [],
                                 'last': None, 'done': False, 'dir': None}
            elif kind == 'packet':
                ep = epochs.get(ident)
                need(ep is not None)
                ts, src, ln = op[2], op[3], op[4]
                need(ep['last'] is None or ts >= ep['last'])
                if not ep['done']:
                    ri = info[ep['rid']]
                    seen = len(ep['feats'])
                    if seen >= ri['width'] and ts-ep['last'] > ri['idle_us']:
                        commit(ep, 'idle', seen, None, None, None)
                    else:
                        if ep['dir'] is None:
                            ep['dir'] = src
                        ep['feats'].append(PAD+ln if src == ep['dir'] else PAD-ln)
                        seen += 1
                        found = None
                        n = len(ep['feats'])
                        for cid, cls, b in ri['prio']:
                            L = len(b)
                            if L > n:
                                continue
                            seg = ep['feats'][n-L:]
                            if all(b[j][0] <= seg[j] <= b[j][1] for j in range(L)):
                                found = (cid, cls, L)
                                break
                        if found:
                            commit(ep, 'segment', seen, found[0], seen-found[2], found[1])
                        elif seen > ri['packet_limit']:
                            commit(ep, 'limit', seen, None, None, None)
                ep['last'] = ts
            else:
                ep = epochs.get(ident)
                need(ep is not None)
                if not ep['done']:
                    commit(ep, 'close', len(ep['feats']), None, None, None)
                del epochs[ident]
                pins[ep['rid']] -= 1
                if pins[ep['rid']] == 0:
                    del pins[ep['rid']]
                    if ep['rid'] != current:
                        residents.discard(ep['rid'])
            at += 1
    need(not epochs)
    return {'catalog': catalog, 'installs': installs, 'decisions': decisions,
            'final': {'current': current, 'resident': sorted(residents), 'used': used()}}
PYEOF
